# Icons the client-side scripts need (cloned from <template id="icon-NAME">).
JS_ICONS = ("check-circle", "x-circle", "alert", "info", "x", "eye", "eye-off", "timer", "send", "flag",
            "eraser", "arrow-left", "arrow-right", "refresh", "check")


MISSING_ICONS: set[str] = set()  # names requested but not defined (checked by tests)


def icon(name: str, cls: str = "", label: str | None = None, size: int | None = None) -> Markup:
    body = P.get(name)
    if body is None:
        MISSING_ICONS.add(name)
        body = P["help"]
    classes = "icon" + (f" {escape(cls)}" if cls else "")
    style = f' style="width:{int(size)}px;height:{int(size)}px"' if size else ""
    aria = f' role="img" aria-label="{escape(label)}"' if label else ' aria-hidden="true"'
    return Markup(f'<svg class="{classes}" viewBox="0 0 24 24" focusable="false"{style}{aria}>{body}</svg>')


def logo_svg() -> Markup:
    """QuizMaster mark: a magnifier-shaped Q whose tail completes a check-mark."""
    return Markup(
        '<svg viewBox="0 0 32 32" aria-hidden="true" focusable="false">'
        '<circle class="q-ring" cx="15" cy="15" r="8.5"/>'
        '<path class="q-tail" d="M18.5 18.5 L25 25"/>'
        '<path class="q-check" d="M11.5 15.2 l2.6 2.6 l5-5.2"/></svg>')
